// Version 15 types omit v16 subpath modules, and dashboard type allowlists skip automatic loading.
// These declarations only support RegisterLanguage imports, so loose module types are sufficient.
declare module 'react-syntax-highlighter/dist/esm/prism';
declare module 'react-syntax-highlighter/dist/esm/prism-light';
declare module 'react-syntax-highlighter/dist/esm/languages/prism/*';
declare module 'react-syntax-highlighter/dist/esm/styles/prism/*';
